//! 🧪️ Actual donated SET controls render explicit structural buttons and every source-bound member page.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType,IfcTypedValue};
fn set_value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(set_value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(set_value).collect()}),_=>panic!("closed source fixture")}}
#[test]
fn donated_set_select_controller_keeps_exact_carriers_explicit_buttons_and_all_original_pages(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-set-select-input.json")).unwrap();for row in law["cases"].as_array().unwrap(){let page_count=if row["id"]=="set-eighteen"{3}else{1};for page in 0..page_count{let snapshot=std::sync::Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|entity|IfcEntity{id:entity["id"].as_str().unwrap().parse().unwrap(),name:entity["name"].as_str().unwrap().into(),args:entity["args"].as_array().unwrap().iter().map(set_value).collect(),complex:entity["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(set_value).collect()}).collect()}).collect(),..Default::default()});let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-set-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let rows=if row["input"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":law["index"],"value":row["input"]}])};let mut request=staged_request(&serde_json::json!({"path":"/entities/0","value":{"$ifcType":law["entity"],"$ifcInputs":rows}}));request.token.action=editing::SET_SNAPSHOT_VALUE_ACTION_ID.into();if page>0{request.page=Some(semio_framework_plugin::action_staging::StagedFormPage{field_offset:"0".into(),diagnostic_offset:"0".into(),choice:Some(semio_framework_plugin::action_staging::StagedFormChoicePage{path:vec!["entities".into(),"0".into(),"args".into(),"1".into()],offset:law["pages"][page]["offset"].as_str().unwrap().into()})});}let mut donor=Some(request);for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;for _ in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("SET draft stays editable: {}",row["id"])}}let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original status")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],row["ready"]);let fields=tree.root.children.iter().skip(1).collect::<Vec<_>>();assert!(fields.len()<=18);let node=fields[0].children.get(0).unwrap();let Component::Select(select)=&node.component else{panic!("complete actual SET SELECT")};assert_eq!(select.items.len(),2);assert!(!node.bindings.is_empty());if row["input"]["kind"]=="typedValue"{let node=fields[1].children.get(0).unwrap();assert!(matches!(&node.component,Component::Button(_)));assert!(!node.bindings.is_empty());if row["id"]=="set-eighteen"{for(local,id)in law["pages"][page]["members"].as_array().unwrap().iter().enumerate(){let node=fields[2+2*local].children.get(0).unwrap();let Component::Input(input)=&node.component else{panic!("exact original page member")};assert_eq!(input.value.as_ref(),id.as_str().unwrap());assert!(!node.bindings.is_empty());let node=fields[3+2*local].children.get(0).unwrap();assert!(matches!(&node.component,Component::Button(_)));assert!(!node.bindings.is_empty());}}}let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();}}
}
